// --- Collect data from each upstream HTTP node ---

// Supabase error_logs: array response → one item per row (or 0 items if none)
const errorLogs = $('Get Error Logs').all().map(i => i.json).filter(r => r && r.event_type);

// Supabase users: array response → one item per row
const knownCustomerIds = new Set(
  $('Get Supabase Users').all()
    .map(i => i.json.stripe_customer_id)
    .filter(Boolean)
);

// Stripe subscriptions: list object { data: [...] } → single item
const stripeResponse = $('Get Stripe Subscriptions').first()?.json ?? {};
const stripeSubs = Array.isArray(stripeResponse.data) ? stripeResponse.data : [];

// --- Find orphaned subscriptions ---
const orphanedSubs = stripeSubs.filter(sub => {
  const cid = typeof sub.customer === 'string' ? sub.customer : sub.customer?.id;
  return cid && !knownCustomerIds.has(cid);
});

const resolvedOrphans = [];

// --- Auto-cancel, refund, and log each orphan ---
for (const sub of orphanedSubs) {
  const customerId = typeof sub.customer === 'string' ? sub.customer : sub.customer?.id;
  const subscriptionId = sub.id;
  const rawInvoice = sub.latest_invoice;
  const latestInvoiceId = typeof rawInvoice === 'string' ? rawInvoice : (rawInvoice?.id ?? null);
  let paymentIntentId = null;

  try {
    // 1. Cancel the subscription
    await $helpers.httpRequest({
      method: 'DELETE',
      url: `https://api.stripe.com/v1/subscriptions/${subscriptionId}`,
      headers: { Authorization: 'Bearer STRIPE_SECRET_KEY_HERE' },
    });

    // 2. Find payment intent via InvoicePayments API
    if (latestInvoiceId) {
      try {
        const paymentsRes = await $helpers.httpRequest({
          method: 'GET',
          url: 'https://api.stripe.com/v1/invoice_payments',
          headers: { Authorization: 'Bearer STRIPE_SECRET_KEY_HERE' },
          qs: { invoice: latestInvoiceId, limit: 5 },
        });
        const defaultPayment = (paymentsRes.data || []).find(p => p.is_default);
        const rawPi = defaultPayment?.payment?.payment_intent;
        paymentIntentId = typeof rawPi === 'string' ? rawPi : (rawPi?.id ?? null);
      } catch (_) { /* non-fatal: proceed without refund */ }
    }

    // 3. Issue refund if payment intent found
    if (paymentIntentId) {
      await $helpers.httpRequest({
        method: 'POST',
        url: 'https://api.stripe.com/v1/refunds',
        headers: {
          Authorization: 'Bearer STRIPE_SECRET_KEY_HERE',
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: `payment_intent=${encodeURIComponent(paymentIntentId)}`,
      });
    }

    // 4. Log resolution to Supabase error_logs
    await $helpers.httpRequest({
      method: 'POST',
      url: 'https://vjptwvubebxjjkxkzqqe.supabase.co/rest/v1/error_logs',
      headers: {
        apikey: 'SUPABASE_SERVICE_ROLE_KEY_HERE',
        Authorization: 'Bearer SUPABASE_SERVICE_ROLE_KEY_HERE',
        'Content-Type': 'application/json',
        Prefer: 'return=minimal',
      },
      body: JSON.stringify({
        event_type: 'orphaned_subscription_auto_resolved',
        error_message: 'Orphaned subscription auto-cancelled and refunded by monthly audit',
        metadata: {
          stripe_customer_id: customerId,
          subscription_id: subscriptionId,
          payment_intent_id: paymentIntentId,
        },
      }),
    });

    resolvedOrphans.push({ customerId, subscriptionId, paymentIntentId, status: 'resolved' });
  } catch (err) {
    resolvedOrphans.push({ customerId, subscriptionId, error: err.message, status: 'failed' });
  }
}

// --- Compile failure report from error_logs ---
const failures = errorLogs.map(log => ({
  user_id: log.user_id,
  stripe_customer_id: log.metadata?.stripe_customer_id,
  event_type: log.event_type,
  created_at: log.created_at,
}));

return [{
  json: {
    failures,
    failureCount: failures.length,
    resolvedOrphans,
    orphanCount: resolvedOrphans.length,
    hasIssues: failures.length > 0 || resolvedOrphans.length > 0,
  },
}];

const { failures, failureCount, resolvedOrphans, orphanCount, hasIssues } = $input.first().json;

let text;

if (!hasIssues) {
  text = '\u2705 Monthly Stripe audit complete \u2014 no orphaned subscriptions or cancellation failures found.';
} else {
  const lines = ['\u26a0\ufe0f Monthly Stripe audit found issues:\n'];

  if (failureCount > 0) {
    lines.push(`*Cancellation failures this month: ${failureCount}*`);
    for (const f of failures) {
      lines.push(`\u2022 user_id: \`${f.user_id || 'N/A'}\`  stripe_customer_id: \`${f.stripe_customer_id || 'N/A'}\`  (${f.event_type})`);
    }
    lines.push('');
  }

  if (orphanCount > 0) {
    lines.push(`*Orphaned subscriptions found and resolved: ${orphanCount}*`);
    for (const o of resolvedOrphans) {
      const icon = o.status === 'resolved' ? '\u2705' : '\u274c';
      lines.push(`${icon} customer: \`${o.customerId}\`  sub: \`${o.subscriptionId}\``);
    }
    lines.push('');
    lines.push('All orphaned subscriptions have been cancelled and refunded automatically. Review error_logs in Supabase for full details.');
  }

  text = lines.join('\n');
}

return [{ json: { text } }];
